{
  "candidate": "cand_0001",
  "headline": "Seed+1: enforce tau2-airline's un-checked policy rules in tool code (bag allowance, payment-method limits, basic-economy/cabin-flown modify guards, enriched errors) and add an explicit step-by-step operating guide to the policy for the mid reader; all guards RAISE only on genuine violations so no compliant call changes.",
  "clusters": [
    {"id": "A", "name": "Checked-bag miscount", "detail": "nonfree_baggages must equal max(0, total - (cabin_base+membership_bonus)*passengers); seed tools accept any value, so a mid reader's miscount silently corrupts the charge/DB state.", "tasks": [], "scope": "WIDESPREAD", "latent": true, "tag": "BEHAVIORAL"},
    {"id": "B", "name": "Illegal payment split or invented payment id", "detail": "Policy caps payments at 1 certificate / 1 credit card / 3 gift cards and requires ids on-profile; seed book_reservation checks presence but not the counts.", "tasks": [], "scope": "WIDESPREAD", "latent": true, "tag": "BEHAVIORAL"},
    {"id": "C", "name": "Basic-economy flight modified / cabin changed after flown", "detail": "Policy forbids modifying basic-economy flight segments and changing cabin once a segment has flown; the API does not check either.", "tasks": [], "scope": "BOUNDED", "latent": true, "tag": "BEHAVIORAL"},
    {"id": "D", "name": "Cancellation when ineligible", "detail": "Cancel allowed only under 24h / airline-cancelled / business / insurance-covered; involves a judgment on whether the stated reason is covered, so enforced in prose not code.", "tasks": [], "scope": "WIDESPREAD", "latent": true, "tag": "KNOWLEDGE"},
    {"id": "E", "name": "Wrong compensation", "detail": "Compensation only on explicit request, after confirming facts, gated by membership/insurance/business, amounts $100xpax (cancel) / $50xpax (delay).", "tasks": [], "scope": "BOUNDED", "latent": true, "tag": "KNOWLEDGE"},
    {"id": "F", "name": "No confirm / action unreported", "detail": "Write actions require explicit yes beforehand and must be stated in the final message the scorer reads.", "tasks": [], "scope": "WIDESPREAD", "latent": true, "tag": "KNOWLEDGE"}
  ],
  "edits": [
    {"id": "E1", "title": "Bag-allowance guard in book_reservation and update_reservation_baggages (+ add-not-remove)", "files": ["tools/tools.py"], "lever": "BEHAVIORAL", "clusters": ["A"], "blast_radius": "MODERATE", "verified": "Standalone run of the exact formula on task-8 args (total=0 -> expected 0 for all memberships) confirms no false fire; fires only when nonfree != policy value, returning the correct value."},
    {"id": "E2", "title": "Payment-method count guard + enriched not-found error in book_reservation", "files": ["tools/tools.py"], "lever": "BEHAVIORAL", "clusters": ["B"], "blast_radius": "MODERATE", "verified": "Task 8 uses 1 certificate -> counts within limits, no fire; error path only adds available=[...] text."},
    {"id": "E3", "title": "Basic-economy flight-change + cabin-after-flown guards in update_reservation_flights", "files": ["tools/tools.py"], "lever": "BEHAVIORAL", "clusters": ["C"], "blast_radius": "BOUNDED", "verified": "Read-through: fires only on flight-segment change of a basic_economy reservation, or cabin change with a flown segment (fail-open on lookup error); inapplicable to task 8."},
    {"id": "E4", "title": "Enriched passenger-count-mismatch error in update_reservation_passengers", "files": ["tools/tools.py"], "lever": "KNOWLEDGE", "clusters": ["F"], "blast_radius": "BOUNDED", "verified": "Error text only; logic unchanged."},
    {"id": "E5", "title": "Append Agent Operating Guide to policy.md (first-steps, confirm-before-write example, bag table+formula+example, payment limits, cancellation decision-chain+example, compensation checklist+amounts, final-message contract, scoped softness clause)", "files": ["policy/policy.md"], "lever": "CONTRACT", "clusters": ["A", "B", "C", "D", "E", "F"], "blast_radius": "WIDE", "verified": "Append-only; no existing constraint removed; binding policy text unchanged."}
  ],
  "skipped": [
    {"title": "Code guard on cancel_reservation eligibility", "reason": "'reason covered by insurance' is a judgment on free text -> not deterministic; a hard guard risks false-positive regressions. Left to prose decision-chain."},
    {"title": "Code guard on send_certificate compensation", "reason": "Eligibility needs confirmed facts + explicit user intent (judgment). Prose only."},
    {"title": "Seat-release-on-cancel", "reason": "Matches tau2 reference behavior; changing it would diverge from the gold DB state."}
  ],
  "techniques": ["in-body deterministic guards (RAISE, never auto-correct, so compliant calls are byte-identical)", "enriched recoverable error returns with available-options + next step", "discriminating-predicate guards for act-vs-refuse", "worked few-shot examples + decision chains tuned for a mid reader", "scoped softness clause that protects the binding policy"]
}
